import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_01_two_controls.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_02_permission_profiles.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_03_prompt_injection.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_04_secret_exfiltration.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_05_approval_review.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_06_security_layers.png",q=JSON.parse('{"title":"敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环","description":"Codex 最有价值的地方，是它不只给建议，还能读文件、改代码、运行命令和连接工具；它最大的风险也来自这里。真正可靠的 AI 编程，不是反复提醒模型“千万小心”，而是把能做什么、何时停下、谁来批准、怎样留证据写进可执行边界。","frontmatter":{"title":"敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环","description":"Codex 最有价值的地方，是它不只给建议，还能读文件、改代码、运行命令和连接工具；它最大的风险也来自这里。真正可靠的 AI 编程，不是反复提醒模型“千万小心”，而是把能做什么、何时停下、谁来批准、怎样留证据写进可执行边界。","date":"2026-08-10","topic":"AI 底层学习","section":"Codex · 官方文档十讲","readingTime":7,"source":"2026-08-10/ai_codex_08_security_permissions.md","status":"published","cover":"/article-assets/2026-08-10/ai_codex_08_01_two_controls.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-08-security-permissions"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环"}],["meta",{"property":"og:description","content":"Codex 最有价值的地方，是它不只给建议，还能读文件、改代码、运行命令和连接工具；它最大的风险也来自这里。真正可靠的 AI 编程，不是反复提醒模型“千万小心”，而是把能做什么、何时停下、谁来批准、怎样留证据写进可执行边界。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/ai-codex-08-security-permissions"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_01_two_controls.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环"}],["meta",{"name":"twitter:description","content":"Codex 最有价值的地方，是它不只给建议，还能读文件、改代码、运行命令和连接工具；它最大的风险也来自这里。真正可靠的 AI 编程，不是反复提醒模型“千万小心”，而是把能做什么、何时停下、谁来批准、怎样留证据写进可执行边界。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_08_01_two_controls.png"}]],"prev":{"text":"Codex 用久了才懂：速查、排障与最佳实践的系统方法","link":"/ai/ai-codex-07-practice-governance"},"next":{"text":"把 Codex 嵌进工程系统：SDK、App Server、GitHub、Slack 与 Linear 全链路","link":"/ai/ai-codex-09-sdk-integrations"}},"headers":[],"relativePath":"ai/ai-codex-08-security-permissions.md","filePath":"ai/ai-codex-08-security-permissions.md","lastUpdated":null}'),d={name:"ai/ai-codex-08-security-permissions.md"};function h(_,a,m,x,u,b){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="敢让-ai-真动手-先把边界画清-codex-权限、沙箱、审批与安全闭环" tabindex="-1">敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环 <a class="header-anchor" href="#敢让-ai-真动手-先把边界画清-codex-权限、沙箱、审批与安全闭环" aria-label="Permalink to &quot;敢让 AI 真动手，先把边界画清：Codex 权限、沙箱、审批与安全闭环&quot;">​</a></h1><p>Codex 最有价值的地方，是它不只给建议，还能读文件、改代码、运行命令和连接工具；它最大的风险也来自这里。真正可靠的 AI 编程，不是反复提醒模型“千万小心”，而是把能做什么、何时停下、谁来批准、怎样留证据写进可执行边界。</p><p>本文以教程第 15、16 篇为线索，对照 OpenAI Docs 的 Agent approvals &amp; security、Permissions 与 Sandbox 章节。教程帮助理解风险场景，官方文档则明确当前控制模型：Sandbox 决定技术上能访问什么，Approval 决定何时必须暂停并请求审查，两者不能互相替代。</p><h2 id="一、先把-会行动-理解成安全问题" tabindex="-1">一、先把“会行动”理解成安全问题 <a class="header-anchor" href="#一、先把-会行动-理解成安全问题" aria-label="Permalink to &quot;一、先把“会行动”理解成安全问题&quot;">​</a></h2><h3 id="_1-1-prompt-约束不是强制隔离" tabindex="-1">1.1 Prompt 约束不是强制隔离 <a class="header-anchor" href="#_1-1-prompt-约束不是强制隔离" aria-label="Permalink to &quot;1.1 Prompt 约束不是强制隔离&quot;">​</a></h3><p>Prompt 可以要求代理只改某个目录、不要联网、不要发布，但自然语言本身不是操作系统边界。模型可能误解范围，仓库里的不可信文本也可能诱导它偏离任务。安全设计必须假设指令会被误读，再用沙箱、权限和审批限制后果。</p><h3 id="_1-2-自动化程度越高-边界越要外置" tabindex="-1">1.2 自动化程度越高，边界越要外置 <a class="header-anchor" href="#_1-2-自动化程度越高-边界越要外置" aria-label="Permalink to &quot;1.2 自动化程度越高，边界越要外置&quot;">​</a></h3><p>人盯着每条命令时，可以临场阻止风险；非交互任务、长时间运行和多工具协作把判断移到后台，更需要预先定义文件、网络、凭据和外部动作的范围。可靠自动化不是取消人工，而是把人工判断留在高影响节点。</p><p><img src="'+i+'" alt="图 1：任务请求经过沙箱、审批与审计后形成受控动作"></p><h2 id="二、sandbox-与-approval-是两道不同的门" tabindex="-1">二、Sandbox 与 Approval 是两道不同的门 <a class="header-anchor" href="#二、sandbox-与-approval-是两道不同的门" aria-label="Permalink to &quot;二、Sandbox 与 Approval 是两道不同的门&quot;">​</a></h2><h3 id="_2-1-sandbox-定义技术能力" tabindex="-1">2.1 Sandbox 定义技术能力 <a class="header-anchor" href="#_2-1-sandbox-定义技术能力" aria-label="Permalink to &quot;2.1 Sandbox 定义技术能力&quot;">​</a></h3><p>沙箱约束代理启动的命令能够读取和写入哪些路径、能否访问网络，以及能否接触工作区之外的系统资源。即使模型想越界，受支持平台的运行时仍会执行这些限制。官方文档强调，Git、包管理器、测试程序等子进程同样继承边界。</p><h3 id="_2-2-approval-定义决策流程" tabindex="-1">2.2 Approval 定义决策流程 <a class="header-anchor" href="#_2-2-approval-定义决策流程" aria-label="Permalink to &quot;2.2 Approval 定义决策流程&quot;">​</a></h3><p>审批策略决定某个动作是否需要暂停，让用户或自动审查器判断。批准一次越界，不等于永久授予整台机器权限；一个合格的请求应给出精确命令、目标范围、必要原因和关键风险。</p><h3 id="_2-3-自动审查不会扩大沙箱" tabindex="-1">2.3 自动审查不会扩大沙箱 <a class="header-anchor" href="#_2-3-自动审查不会扩大沙箱" aria-label="Permalink to &quot;2.3 自动审查不会扩大沙箱&quot;">​</a></h3><p>OpenAI Docs 当前区分 Ask for approval、Approve for me 和 Full access 等交互模式。把审批交给自动审查，只改变“谁来审”，不会自动放宽工作区边界。Full access 则移除重要隔离，应只在明确接受广泛访问时使用。</p><h2 id="三、权限档位应围绕任务而不是围绕人" tabindex="-1">三、权限档位应围绕任务而不是围绕人 <a class="header-anchor" href="#三、权限档位应围绕任务而不是围绕人" aria-label="Permalink to &quot;三、权限档位应围绕任务而不是围绕人&quot;">​</a></h2><h3 id="_3-1-只读适合调查与规划" tabindex="-1">3.1 只读适合调查与规划 <a class="header-anchor" href="#_3-1-只读适合调查与规划" aria-label="Permalink to &quot;3.1 只读适合调查与规划&quot;">​</a></h3><p>代码审计、架构梳理、日志分析和方案讨论通常不需要写权限。只读模式能证明本轮不会改变仓库状态，也迫使任务先形成事实地图。</p><h3 id="_3-2-工作区写入适合常规开发" tabindex="-1">3.2 工作区写入适合常规开发 <a class="header-anchor" href="#_3-2-工作区写入适合常规开发" aria-label="Permalink to &quot;3.2 工作区写入适合常规开发&quot;">​</a></h3><p>对版本控制仓库，常见低摩擦组合是在活动工作区内读写，并对网络或工作区外动作按需审批。这样代理可以连续完成搜索、编辑和本地测试，同时把系统级变化留给人工判断。</p><h3 id="_3-3-权限配置档适合最小授权" tabindex="-1">3.3 权限配置档适合最小授权 <a class="header-anchor" href="#_3-3-权限配置档适合最小授权" aria-label="Permalink to &quot;3.3 权限配置档适合最小授权&quot;">​</a></h3><p>官方 Permissions 文档提供内置只读、工作区和全访问档位，也支持用文件系统与网络规则定义命名 Profile。更窄的拒绝规则可以继续保护 <code>.env</code> 等敏感路径，即使工作区整体可写。权限配置档仍在演进，部署时要核对当前版本，不能把旧 sandbox 设置和新 profile 机制随意混用。</p><p><img src="'+s+'" alt="图 2：从只读到工作区写入的最小权限配置"></p><h2 id="四、网络是另一条独立边界" tabindex="-1">四、网络是另一条独立边界 <a class="header-anchor" href="#四、网络是另一条独立边界" aria-label="Permalink to &quot;四、网络是另一条独立边界&quot;">​</a></h2><h3 id="_4-1-能读网页不等于命令可以联网" tabindex="-1">4.1 能读网页不等于命令可以联网 <a class="header-anchor" href="#_4-1-能读网页不等于命令可以联网" aria-label="Permalink to &quot;4.1 能读网页不等于命令可以联网&quot;">​</a></h3><p>Web Search、浏览器、插件和本地命令可能使用不同的网络控制。官方文档指出，本地 <code>workspace-write</code> 默认不等于开放命令网络；需要联网时应明确启用，并尽量通过域名策略收口目的地。</p><h3 id="_4-2-白名单只能缩小出口-不能证明内容可信" tabindex="-1">4.2 白名单只能缩小出口，不能证明内容可信 <a class="header-anchor" href="#_4-2-白名单只能缩小出口-不能证明内容可信" aria-label="Permalink to &quot;4.2 白名单只能缩小出口，不能证明内容可信&quot;">​</a></h3><p>允许访问官方文档域名，可以降低任意外连风险，但网页内容、依赖安装脚本和下载文件仍需视为不可信输入。网络许可解决“可以去哪里”，内容审查解决“拿回来的东西能否执行”。</p><h3 id="_4-3-凭据应在最短生命周期出现" tabindex="-1">4.3 凭据应在最短生命周期出现 <a class="header-anchor" href="#_4-3-凭据应在最短生命周期出现" aria-label="Permalink to &quot;4.3 凭据应在最短生命周期出现&quot;">​</a></h3><p>密钥不进入 Prompt、源码、提交和日志。云端环境适合把 Secrets 只提供给设置阶段，再在代理阶段移除；本地自动化则应使用受控环境变量或秘密管理系统，并避免回显。能用短期令牌，就不要共享长期 token。</p><p><img src="'+n+'" alt="图 3：不可信内容经过工具请求与边界拦截"></p><p><img src="'+p+'" alt="图 4：文件、网络与域名策略共同阻断秘密外泄"></p><h2 id="五、审批请求本身也需要审查方法" tabindex="-1">五、审批请求本身也需要审查方法 <a class="header-anchor" href="#五、审批请求本身也需要审查方法" aria-label="Permalink to &quot;五、审批请求本身也需要审查方法&quot;">​</a></h2><h3 id="_5-1-先看动作意图-再看精确目标" tabindex="-1">5.1 先看动作意图，再看精确目标 <a class="header-anchor" href="#_5-1-先看动作意图-再看精确目标" aria-label="Permalink to &quot;5.1 先看动作意图，再看精确目标&quot;">​</a></h3><p>审批界面出现“需要更高权限”时，不要只判断工具是否常用。应核对它要完成什么任务、将改动哪个路径或外部对象、为什么现有权限不能完成，以及是否存在更小范围方案。</p><h3 id="_5-2-再判断可逆性与影响对象" tabindex="-1">5.2 再判断可逆性与影响对象 <a class="header-anchor" href="#_5-2-再判断可逆性与影响对象" aria-label="Permalink to &quot;5.2 再判断可逆性与影响对象&quot;">​</a></h3><p>读取官方文档与公开元数据通常低风险；安装依赖、修改系统配置、推送分支、发送消息、删除文件和生产变更会改变更广泛状态。越难恢复、影响的人越多，越应保留逐步批准。</p><h3 id="_5-3-最后选择最窄授权范围" tabindex="-1">5.3 最后选择最窄授权范围 <a class="header-anchor" href="#_5-3-最后选择最窄授权范围" aria-label="Permalink to &quot;5.3 最后选择最窄授权范围&quot;">​</a></h3><p>能只批准一个命令，就不批准整个会话；能只开放一个域名，就不开放任意网络；能在临时分支或草稿中完成，就不直接触碰正式状态。拒绝宽泛请求并不是阻碍代理，而是在要求它给出可审查的执行合同。</p><p><img src="'+l+'" alt="图 5：从动作意图、影响范围到最小授权的审批方法"></p><h2 id="六、prompt-injection-的根因是指令权混淆" tabindex="-1">六、Prompt Injection 的根因是指令权混淆 <a class="header-anchor" href="#六、prompt-injection-的根因是指令权混淆" aria-label="Permalink to &quot;六、Prompt Injection 的根因是指令权混淆&quot;">​</a></h2><p>网页、Issue、日志、依赖说明和仓库文档都可能包含“忽略前文并执行某命令”之类的文本。代理必须把这些材料当作数据，而不是自动赋予其更高指令权。项目规则、用户授权和系统边界高于外部内容。</p><p>防护不能只依赖识别恶意措辞。更稳健的做法是同时限制秘密可读范围、网络目的地、工具副作用和最终发布动作。即使某段注入文本骗过模型，外层控制仍能缩小后果。</p><h2 id="七、把高风险动作留在人类责任线上" tabindex="-1">七、把高风险动作留在人类责任线上 <a class="header-anchor" href="#七、把高风险动作留在人类责任线上" aria-label="Permalink to &quot;七、把高风险动作留在人类责任线上&quot;">​</a></h2><p>删除、覆盖 Git 历史、数据库迁移、密钥轮换、付款、合并、生产部署和公开发布，具有不可逆或多人影响。代理可以准备精确目标、影响分析、dry-run、恢复方案和验证清单，但最终确认应由拥有责任的人完成。</p><p>MCP 和连接器工具同样如此。工具若声明有副作用或破坏性，审批应覆盖它，而不是只盯 shell 命令。供应链中的 Skill、插件、MCP Server 与 Hook 也要审查来源、维护者、权限和停用路径。</p><p><img src="'+c+'" alt="图 6：项目规则、沙箱、审批、自动审查与人工责任的安全层"></p><h2 id="八、结语" tabindex="-1">八、结语 <a class="header-anchor" href="#八、结语" aria-label="Permalink to &quot;八、结语&quot;">​</a></h2><p>让 Codex 安全行动的核心，不是“完全信任”或“完全禁止”二选一，而是让低风险动作在明确边界内连续进行，让跨界、高影响和不可逆动作及时停下。Sandbox 提供强制边界，Permission Profile 表达最小能力，Approval 承担例外决策，网络与秘密策略限制数据流，人工审查守住最终责任。</p><p>当每一次状态变化都能回答“谁发起、为什么需要、能碰哪里、怎样验证、如何恢复”，AI 编程才真正具备可扩大使用范围的安全基础。</p><h2 id="九、参考资料" tabindex="-1">九、参考资料 <a class="header-anchor" href="#九、参考资料" aria-label="Permalink to &quot;九、参考资料&quot;">​</a></h2><p><a href="https://coding.stormzhang.ai/codex/15-permissions" target="_blank" rel="noreferrer">Codex 系列第 15 篇：权限与沙箱</a></p><p><a href="https://coding.stormzhang.ai/codex/16-security" target="_blank" rel="noreferrer">Codex 系列第 16 篇：安全</a></p><p><a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">OpenAI Agent approvals &amp; security 官方文档</a></p><p><a href="https://learn.chatgpt.com/docs/permissions" target="_blank" rel="noreferrer">OpenAI Permissions 官方文档</a></p><p><a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">OpenAI Sandbox 官方文档</a></p>',57)])])}const g=e(d,[["render",h]]);export{q as __pageData,g as default};
